// Starlight config for the @hawkeyexl/inference documentation site.
//
// The six sidebar sections are the CUJ-first tracks defined in
// content-strategy/information_architecture/proposed-ia.md. Their order is fixed here;
// pages within each are autogenerated, so adding a page to a directory adds it to the nav.
//
// The `@examples` alias points at the repo-root examples/ directory. Pages import those
// files with `?raw` and render them, so a code sample on a page cannot drift from the file
// Doc Detective executes in CI. See adrs/01005.

import { fileURLToPath } from "node:url";

import starlight from "@astrojs/starlight";
import { defineConfig } from "astro/config";

const examplesDir = fileURLToPath(new URL("../examples", import.meta.url));
const repoRoot = fileURLToPath(new URL("..", import.meta.url));

export default defineConfig({
  site: "https://hawkeyexl.github.io",
  base: "/inference",
  integrations: [
    starlight({
      title: "@hawkeyexl/inference",
      description:
        "Schema-constrained LLM completion across four providers, with caching, cost accounting, and an LLM-as-judge ensemble.",
      social: [
        {
          icon: "github",
          label: "GitHub",
          href: "https://github.com/hawkeyexl/inference",
        },
      ],
      sidebar: [
        { label: "Get started", items: [{ autogenerate: { directory: "get-started" } }] },
        { label: "Judge & consensus", items: [{ autogenerate: { directory: "judge" } }] },
        { label: "Structured extraction", items: [{ autogenerate: { directory: "extract" } }] },
        { label: "Run models locally", items: [{ autogenerate: { directory: "local" } }] },
        { label: "Keep it working", items: [{ autogenerate: { directory: "keep-it-working" } }] },
        { label: "Reference", items: [{ autogenerate: { directory: "reference" } }] },
      ],
    }),
  ],
  vite: {
    resolve: {
      alias: { "@examples": examplesDir },
    },
    server: {
      // examples/ lives outside docs/, so Vite needs explicit permission to read it.
      fs: { allow: [repoRoot] },
    },
  },
});
